(7533, 6040, COALESCE((SELECT id FROM categorias WHERE LOWER(nombre) LIKE '%moda y ropa%' OR LOWER(nombre) LIKE '%moda%' LIMIT 1), 2), 'Rolex Submariner Watch - Lorduy', 'rolex-submariner-watch-7533', 'The Rolex Submariner is a legendary dive watch with a rich history. Known for its durability and water resistance, it''s a symbol of adventure and exploration. Garantía oficial de 12 meses con despacho asegurado en Cartagena de Indias.', 55300000, 44240000, 16, 'SEED-PROD-7533', 'Lorduy', 'NUEVO', TRUE, FALSE, 4.8, 23, 4, NOW() - INTERVAL '45 days', NOW() - INTERVAL '45 days'),
