(7535, 6040, COALESCE((SELECT id FROM categorias WHERE LOWER(nombre) LIKE '%moda y ropa%' OR LOWER(nombre) LIKE '%moda%' LIMIT 1), 2), 'Green Oval Earring - Lorduy', 'green-oval-earring-7535', 'The Green Oval Earring is a stylish and versatile accessory with a unique oval shape. Whether for casual or dressy occasions, its green hue and contemporary design make it a standout piece. Garantía oficial de 12 meses con despacho asegurado en Cartagena de Indias.', 99000, NULL, 25, 'SEED-PROD-7535', 'Lorduy', 'NUEVO', TRUE, FALSE, 5.0, 12, 2, NOW() - INTERVAL '16 days', NOW() - INTERVAL '16 days'),
(7536, 6040, COALESCE((SELECT id FROM categorias WHERE LOWER(nombre) LIKE '%moda y ropa%' OR LOWER(nombre) LIKE '%moda%' LIMIT 1), 2), 'Tropical Earring - Lorduy', 'tropical-earring-7536', 'The Tropical Earring is a fun and playful accessory inspired by tropical elements. Featuring vibrant colors and a lively design, it''s perfect for adding a touch of summer to your look. Garantía oficial de 12 meses con despacho asegurado en Cartagena de Indias.', 79000, 71100, 22, 'SEED-PROD-7536', 'Lorduy', 'NUEVO', TRUE, FALSE, 4.8, 9, 1, NOW() - INTERVAL '45 days', NOW() - INTERVAL '45 days'),
