(7538, 6040, COALESCE((SELECT id FROM categorias WHERE LOWER(nombre) LIKE '%moda y ropa%' OR LOWER(nombre) LIKE '%moda%' LIMIT 1), 2), 'Rolex Cellini Moonphase - Lorduy', 'rolex-cellini-moonphase-7538', 'The Rolex Cellini Moonphase watch is a masterpiece of horology. Featuring a moon phase complication, it showcases the craftsmanship and elegance that Rolex is renowned for. Garantía oficial de 12 meses con despacho asegurado en Cartagena de Indias.', 63200000, NULL, 17, 'SEED-PROD-7538', 'Lorduy', 'NUEVO', TRUE, FALSE, 4.8, 23, 5, NOW() - INTERVAL '22 days', NOW() - INTERVAL '22 days'),
(7539, 6040, COALESCE((SELECT id FROM categorias WHERE LOWER(nombre) LIKE '%moda y ropa%' OR LOWER(nombre) LIKE '%moda%' LIMIT 1), 2), 'Rolex Datejust Women - Lorduy', 'rolex-datejust-women-7539', 'The Rolex Datejust Women''s watch is an iconic timepiece designed for women. With a timeless design and a date complication, it offers both elegance and functionality. Garantía oficial de 12 meses con despacho asegurado en Cartagena de Indias.', 43450000, 39105000, 40, 'SEED-PROD-7539', 'Lorduy', 'NUEVO', TRUE, FALSE, 4.8, 23, 2, NOW() - INTERVAL '36 days', NOW() - INTERVAL '36 days'),
